def canon(cells, allow_reflect=True):
    pts=list(cells); forms=[]
    for refl in ([1,-1] if allow_reflect else [1]):
      for rot in range(4):
        q=[]
        for x,y in pts:
          a=x; b=y*refl
          for _ in range(rot): a,b=b,-a
          q.append((a,b))
        mx=min(x for x,y in q); my=min(y for x,y in q)
        forms.append(tuple(sorted((x-mx,y-my) for x,y in q)))
    return min(forms)
